import { execFile } from 'node:child_process';
import { promisify } from 'node:util';

const execFileAsync = promisify(execFile);

async function getModelFromStatus() {
  const { stdout, stderr } = await execFileAsync('claude', ['-p', '/status'], {
    windowsHide: true,
    maxBuffer: 1024 * 1024,
  });

  const out = `${stdout || ''}${stderr || ''}`.trim();
  if (!out) {
    throw new Error('No output from claude CLI.');
  }

  if (/isn\'t available in this environment\./i.test(out)) {
    throw new Error(
      '/status is not available in non-interactive mode (-p). Run claude interactively or use SDK initializationResult().'
    );
  }

  const match = out.match(/^Model:\s*(.+)$/im);
  if (!match) {
    throw new Error(`Could not find a Model line in /status output:\n${out}`);
  }

  const modelLine = match[1].trim();
  const alias = modelLine.split(/\s+/)[0];

  return { alias, modelLine, raw: out };
}

(async () => {
  try {
    const result = await getModelFromStatus();
    console.log(JSON.stringify(result, null, 2));
  } catch (err) {
    console.error(err?.message || err);
    process.exit(1);
  }
})();
