import { exec } from 'node:child_process';
import { promisify } from 'node:util';

const execAsync = promisify(exec);

async function getSessionModel(sessionId) {
  if (!sessionId) throw new Error('Session ID is required.');
  const cli = process.platform === 'win32' ? 'claude.cmd' : 'claude';
  const cmd = `${cli} -p --verbose --output-format stream-json --resume ${sessionId} "ok"`;

  const { stdout, stderr } = await execAsync(cmd, {
    windowsHide: true,
    maxBuffer: 4 * 1024 * 1024,
  });

  const combined = `${stdout || ''}\n${stderr || ''}`;
  const lines = combined
    .split(/\r?\n/)
    .map((l) => l.trim())
    .filter(Boolean);

  for (const line of lines) {
    try {
      const evt = JSON.parse(line);
      if (evt?.type === 'system' && evt?.subtype === 'init' && evt?.model) {
        return {
          sessionId: evt.session_id || sessionId,
          model: evt.model,
          permissionMode: evt.permissionMode || null,
          claudeCodeVersion: evt.claude_code_version || null,
        };
      }
    } catch {
      // ignore non-JSON lines
    }
  }

  throw new Error(`Could not find system init model in CLI output. First lines:\n${lines.slice(0, 10).join('\n')}`);
}

(async () => {
  try {
    const sessionId = process.argv[2];
    const result = await getSessionModel(sessionId);
    console.log(JSON.stringify(result, null, 2));
  } catch (err) {
    console.error(err?.message || err);
    process.exit(1);
  }
})();
