import { spawn } from 'node:child_process';
import os from 'node:os';
import path from 'node:path';

function runSqlite(dbPath, sql) {
  return new Promise((resolve, reject) => {
    const child = spawn('sqlite3', [dbPath, sql], {
      windowsHide: true,
      stdio: ['ignore', 'pipe', 'pipe'],
      shell: false,
    });

    let stdout = '';
    let stderr = '';

    child.stdout.on('data', (d) => {
      stdout += d.toString();
    });

    child.stderr.on('data', (d) => {
      stderr += d.toString();
    });

    child.on('error', (err) => reject(err));
    child.on('close', (code) => {
      if (code !== 0) {
        reject(new Error(stderr.trim() || `sqlite3 exited with code ${code}`));
        return;
      }
      resolve(stdout);
    });
  });
}

function parseRow(line) {
  const [id, modelProvider, model, reasoningEffort, updatedAtMs] = line.split('|');
  if (!id) return null;
  return {
    sessionId: id,
    modelProvider: modelProvider || null,
    model: model || null,
    reasoningEffort: reasoningEffort || null,
    updatedAtMs: updatedAtMs ? Number(updatedAtMs) : null,
    updatedAtIso: updatedAtMs ? new Date(Number(updatedAtMs)).toISOString() : null,
  };
}

async function main() {
  const sessionIds = process.argv.slice(2);
  if (sessionIds.length === 0) {
    throw new Error('Usage: node scripts/codex-session-model.mjs <sessionId> [sessionId2 ...]');
  }

  const dbPath = path.join(os.homedir(), '.codex', 'state_5.sqlite');

  const escapedIds = sessionIds.map((id) => `'${id.replace(/'/g, "''")}'`).join(', ');
  const sql = `SELECT id, model_provider, model, reasoning_effort, updated_at_ms FROM threads WHERE id IN (${escapedIds}) ORDER BY updated_at_ms DESC;`;

  const raw = await runSqlite(dbPath, sql);
  const rows = raw
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean)
    .map(parseRow)
