function runCommand(cmd, args) {
  return new Promise((resolve, reject) => {
    const child = spawn(cmd, args, {
      windowsHide: true,
      stdio: ['ignore', 'pipe', 'pipe'],
      shell: false,
    });

    let stdout = '';
    let stderr = '';

    child.stdout.on('data', (d) => (stdout += d.toString()));
    child.stderr.on('data', (d) => (stderr += d.toString()));
    child.on('error', reject);
    child.on('close', (code) => resolve({ code, stdout, stderr }));
  });
}

function parseLiveModel(stderr) {
  const m = stderr.match(/resuming session with different model:\s*previous=([^,\s]+),\s*current=([^\s]+)/i);
  if (!m) return null;
  return {
    previousModel: m[1],
    currentModel: m[2],
    source: 'runtime_resume_warning',
  };
}

function parseDbRow(line) {
  const [id, provider, model, effort, updatedAtMs] = line.split('|');
  if (!id) return null;
  return {
    sessionId: id,
    modelProvider: provider || null,
    model: model || null,
    reasoningEffort: effort || null,
    updatedAtMs: updatedAtMs ? Number(updatedAtMs) : null,
    source: 'local_state_db',
  };
}

async function readDbModel(sessionId) {
  const dbPath = path.join(os.homedir(), '.codex', 'state_5.sqlite');
  const sql = `SELECT id, model_provider, model, reasoning_effort, updated_at_ms FROM threads WHERE id='${sessionId.replace(/'/g, "''")}';`;
  const out = await runCommand('sqlite3', [dbPath, sql]);
  const row = out.stdout.split(/\r?\n/).map((l) => l.trim()).find(Boolean);
  return row ? parseDbRow(row) : null;
}

async function getModel(sessionId) {
  const codexCmd = process.platform === 'win32' ? 'codex.cmd' : 'codex';
  const res = await runCommand(codexCmd, ['exec', 'resume', sessionId, 'ping', '--json']);

  const live = parseLiveModel(res.stderr);
  if (live) {
    return {
      sessionId,
      model: live.currentModel,
      previousModel: live.previousModel,
      source: live.source,
    };
  }

  const db = await readDbModel(sessionId);
  if (db) {
    return {
      sessionId,
      model: db.model,
      modelProvider: db.modelProvider,
      reasoningEffort: db.reasoningEffort,
      updatedAtMs: db.updatedAtMs,
      source: db.source,
    };
  }

  return {
    sessionId,
    model: null,
    source: 'not_found',
  };
}

(async () => {
  try {
    const sessionIds = process.argv.slice(2);
    if (sessionIds.length === 0) {
      throw new Error('Usage: node scripts/codex-session-current-model.mjs <sessionId> [sessionId2 ...]');
    }

    const results = [];
    for (const id of sessionIds) {
