import readline from 'node:readline';

function runSqlite(dbPath, sql) {
  return new Promise((resolve, reject) => {
    const cmd = `sqlite3 "${dbPath}" "${sql.replace(/"/g, '""')}"`;
    const child = spawn(cmd, { shell: true, windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] });
    let stdout = '';
    let stderr = '';
    child.stdout.on('data', (d) => (stdout += d.toString()));
    child.stderr.on('data', (d) => (stderr += d.toString()));
    child.on('error', reject);
    child.on('close', (code) => {
      if (code !== 0) return reject(new Error(stderr.trim() || `sqlite3 exited with ${code}`));
      resolve(stdout);
    });
  });
}

async function parseRollout(rolloutPath) {
  if (!rolloutPath || !fs.existsSync(rolloutPath)) return null;

  const stream = fs.createReadStream(rolloutPath, { encoding: 'utf8' });
  const rl = readline.createInterface({ input: stream, crlfDelay: Infinity });

  let latestModel = null;
  let latestEffort = null;
  let latestTimestamp = null;
  let initialProvider = null;

  for await (const line of rl) {
    if (!line.trim()) continue;
    let obj;
    try {
      obj = JSON.parse(line);
    } catch {
      continue;
    }

    if (obj?.type === 'session_meta') {
      initialProvider = obj?.payload?.model_provider || initialProvider;
    }

    if (obj?.type === 'turn_context') {
      const model = obj?.payload?.model;
      if (model) {
        latestModel = model;
        latestEffort = obj?.payload?.effort || latestEffort;
        latestTimestamp = obj?.timestamp || latestTimestamp;
      }
    }
  }

  if (!latestModel) return null;
  return {
    model: latestModel,
    reasoningEffort: latestEffort || null,
    observedAt: latestTimestamp || null,
    modelProvider: initialProvider || null,
    source: 'rollout_turn_context',
  };
}

async function getSessionCurrentModel(sessionId) {
  const dbPath = path.join(os.homedir(), '.codex', 'state_5.sqlite');
  const safeId = sessionId.replace(/'/g, "''");
  const sql = `SELECT id, rollout_path, model_provider, model, reasoning_effort, updated_at_ms FROM threads WHERE id='${safeId}' LIMIT 1;`;
  const row = (await runSqlite(dbPath, sql)).split(/\r?\n/).find(Boolean);
  if (!row) return { sessionId, model: null, source: 'not_found' };

  const [id, rolloutPath, modelProviderDb, modelDb, effortDb, updatedAtMsDb] = row.split('|');
  const fromRollout = await parseRollout(rolloutPath);

  if (fromRollout) {
    return {
      sessionId: id,
      model: fromRollout.model,
      reasoningEffort: fromRollout.reasoningEffort,
      modelProvider: fromRollout.modelProvider || modelProviderDb || null,
      observedAt: fromRollout.observedAt,
      rolloutPath,
      source: fromRollout.source,
      fallbackDbModel: modelDb || null,
    };
  }

  return {
    sessionId: id,
    model: modelDb || null,
    reasoningEffort: effortDb || null,
    modelProvider: modelProviderDb || null,
    updatedAtMs: updatedAtMsDb ? Number(updatedAtMsDb) : null,
    rolloutPath,
    source: 'threads_table_fallback',
  };
}

(async () => {
  try {
    const sessionIds = process.argv.slice(2);
    if (!sessionIds.length) {
      throw new Error('Usage: node scripts/codex-session-current-model.mjs <sessionId> [sessionId2 ...]');
    }

