import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

function walk(dir, out = []) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const e of entries) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, out);
    else out.push(p);
  }
  return out;
}

function findSessionFiles(baseDir, sessionId) {
  const prefix = sessionId.slice(0, 8).toLowerCase();
  const tmpRoot = path.join(baseDir, 'tmp');
  if (!fs.existsSync(tmpRoot)) return [];
  const all = walk(tmpRoot).filter((p) => p.toLowerCase().endsWith('.jsonl'));
  return all.filter((p) => p.toLowerCase().includes(`-${prefix}.jsonl`));
}

function extractLatestModelFromJsonl(filePath) {
  const text = fs.readFileSync(filePath, 'utf8');
  const lines = text.split(/\r?\n/).filter(Boolean);
  let last = null;
  for (const line of lines) {
    try {
      const obj = JSON.parse(line);
      if (obj?.type === 'gemini' && obj?.model) {
        last = {
          model: obj.model,
          timestamp: obj.timestamp || null,
          filePath,
        };
      }
    } catch {
      // ignore bad lines
    }
  }
  return last;
}

function resolveLatestSessionIdFromList(baseDir, cwd) {
  // Read recent cache by searching project tmp chats and taking newest file.
  const tmpRoot = path.join(baseDir, 'tmp');
  if (!fs.existsSync(tmpRoot)) return null;
  const projectName = path.basename(cwd).toLowerCase();
  const candidateDir = path.join(tmpRoot, projectName, 'chats');
  const dirs = [candidateDir, tmpRoot].filter((d, i, a) => fs.existsSync(d) && a.indexOf(d) === i);
  let newest = null;
  for (const d of dirs) {
    const files = walk(d).filter((p) => p.toLowerCase().endsWith('.jsonl'));
    for (const f of files) {
      const st = fs.statSync(f);
      if (!newest || st.mtimeMs > newest.mtimeMs) newest = { file: f, mtimeMs: st.mtimeMs };
    }
  }
  if (!newest) return null;
  const m = newest.file.match(/-([a-f0-9]{8})\.jsonl$/i);
  return m ? m[1].toLowerCase() : null;
}

(function main() {
  const baseDir = path.join(os.homedir(), '.gemini');
  const arg = (process.argv[2] || 'latest').trim();
  const cwd = process.cwd();

  let sessionId = arg;
  if (arg === 'latest') {
    const latestPrefix = resolveLatestSessionIdFromList(baseDir, cwd);
    if (!latestPrefix) throw new Error('Could not resolve latest session from local Gemini cache.');
    sessionId = latestPrefix;
  }

  const files = findSessionFiles(baseDir, sessionId);
  if (!files.length) throw new Error(`No local Gemini chat jsonl found for session id/prefix: ${sessionId}`);

  let best = null;
  for (const f of files) {
    const found = extractLatestModelFromJsonl(f);
    if (!found) continue;
    const t = found.timestamp ? Date.parse(found.timestamp) : 0;
    if (!best || t > Date.parse(best.timestamp || 0)) best = found;
  }

  if (!best) throw new Error(`Found files for ${sessionId}, but none had a model field.`);

  console.log(JSON.stringify({
    requested: arg,
    resolvedSessionPrefix: sessionId,
    model: best.model,
    observedAt: best.timestamp,
    source: 'gemini_local_tmp_jsonl',
    filePath: best.filePath,
  }, null, 2));
})();

