import { spawn } from 'node:child_process';

function runWsl(script) {
  return new Promise((resolve, reject) => {
    const child = spawn('wsl', ['-e', 'bash', '-lc', script], { windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] });
    let stdout = '';
    let stderr = '';
    child.stdout.on('data', (d) => (stdout += d.toString()));
    child.stderr.on('data', (d) => (stderr += d.toString()));
    child.on('error', reject);
    child.on('close', (code) => resolve({ code, stdout, stderr }));
  });
}

async function getCursorModel(chatId) {
  if (!chatId) throw new Error('Usage: node scripts/cursor-session-current-model.mjs <chatId>');

  const escaped = chatId.replace(/'/g, "'\\''");
  const findCmd = `find ~/.cursor/chats -mindepth 2 -maxdepth 2 -type d -name '${escaped}' | head -n 1`;
  const found = await wsl(findCmd);
  const dir = found.stdout.trim();
  if (!dir) throw new Error(`Chat ID not found in WSL Cursor storage: ${chatId}`);

  const dbPath = `${dir}/store.db`;
  const sql = `SELECT value FROM meta WHERE key='0' LIMIT 1;`;
  const q = await runWsl(`sqlite3 '${dbPath}' \"${sql}\"`);
  const hex = q.stdout.trim();
  if (!hex) throw new Error(`No metadata found in ${dbPath}`);

  let jsonText;
  try {
    jsonText = Buffer.from(hex, 'hex').toString('utf8');
  } catch {
    throw new Error('Failed to decode metadata hex from Cursor store.db');
  }

  let meta;
  try {
    meta = JSON.parse(jsonText);
  } catch {
    throw new Error('Failed to parse Cursor metadata JSON');
  }

  const model = meta?.modelDetails?.modelName || meta?.modelDetails?.model || meta?.lastUsedModel || meta?.model || null;
  const effort = meta?.modelDetails?.thinkingLevel || meta?.modelDetails?.reasoningEffort || null;
  
  console.log("==> Model: ", model);
  console.log("===> Effort: ", effort);
  
  const modelHints = [];
  for (const [k, v] of Object.entries(meta || {})) {
    if (/model|reason|think/i.test(k)) modelHints.push({ key: k, value: v });
  }

  console.log(JSON.stringify({
    chatId,
    model,
    reasoningEffort: effort,
    source: 'wsl_cursor_storedb_meta',
    dbPath,
    debugTopLevelKeys: Object.keys(meta || {}),
    debugModelHints: modelHints,
  }, null, 2));
}

getCursorModel(process.argv[2]).catch((err) => {
  console.error(err?.message || err);
  process.exit(1);
});

